const todas = $input.all().map((i) => i.json);
const items = todas.filter((n) => !n.__invalida)
  .sort((a, b) => (a.prioridad || 3) - (b.prioridad || 3));
if (items.length === 0) {
  if (todas.length === 0) return [];
  // Habia noticias pero ninguna se pudo resumir: que lo avise el Error workflow.
  throw new Error('Ninguna de las ' + todas.length + ' noticias se pudo resumir: ' + (todas[0].motivo || 'IA no disponible'));
}
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram rechaza mensajes de mas de 4096 caracteres. Se parte por bloques
// completos (nunca a mitad de una etiqueta HTML) y se numeran las partes.
function trocear(cabecera, bloques, pie, max = 3900) {
  const SEP = '\n\n━━━━━━━━━━\n\n';
  const partes = [];
  let actual = cabecera;
  let primero = true;
  for (const b of bloques) {
    const candidato = primero ? actual + b : actual + SEP + b;
    if (!primero && candidato.length > max) { partes.push(actual); actual = b; }
    else actual = candidato;
    primero = false;
  }
  if ((actual + pie).length > max) { partes.push(actual); actual = pie.trim(); }
  else actual += pie;
  partes.push(actual);
  return partes.map((texto, i) => ({ json: {
    texto: partes.length > 1 ? texto + '\n<i>(' + (i + 1) + '/' + partes.length + ')</i>' : texto,
  } }));
}
const fecha = new Date().toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });
const icono = { alta: '🔥', media: '📌', baja: '📎' };

const bloques = items.map((n, i) =>
  `${icono[n.relevancia] || '📰'} <b>${i + 1}. ${n.titulo}</b>\n${n.resumen}` +
  (n.enlace ? `\n<a href="${esc(n.enlace)}">🔗 Leer noticia</a>` : '')
);
const omitidas = todas.length - items.length;
return trocear(
  `📰 <b>TUS NOTICIAS</b>\n<i>${fecha}</i>\n\n━━━━━━━━━━\n\n`,
  bloques,
  `\n\n━━━━━━━━━━\n<i>${items.length} noticia(s)${omitidas ? ' · ' + omitidas + ' sin resumen' : ''}</i>`,
);

// Falla pronto, con un mensaje que dice QUE falta y DONDE se pone, en vez
// de un 401 o un "chat not found" tres nodos mas tarde. El Error workflow
// ("Sistema - Gestor de errores") convierte este error en un aviso.
const requeridas = {
  AC_API_URL: 'URL del backend; la pone el instalador',
  AC_SERVICE_TOKEN: 'panel > AI > Automation token',
  AC_PROFILE_ID: 'launcher > Ajustes > ID del perfil activo',
  TELEGRAM_CHAT_ID: 'launcher > Ajustes > Chat ID de Telegram',
  TELEGRAM_NOTICIAS_TOKEN: 'launcher > Ajustes > Bot Noticias',
};
const vacia = (v) => !String(v || '').trim() || /^PEGA_AQUI/i.test(String(v).trim());
const faltan = Object.entries(requeridas).filter(([k]) => vacia($env[k]));
if (faltan.length) {
  throw new Error('Configuracion incompleta: ' +
    faltan.map(([k, donde]) => k + ' (' + donde + ')').join('; '));
}
return $input.all();

